    "statement": "1등급: 항생제 + 조기 복강경 담낭절제술. 2등급: 수술 위험이 낮으면(CCI ≤ 5, ASA-PS ≤ 2) 숙련된 센터에서 항생제 + 조기 복강경 담낭절제술, 높으면 항생제 + 담낭배액 후 간격 담낭절제. 3등급: 집중치료 + 항생제 + 담낭배액이 기본이고, 장기부전이 빨리 회복되는 종류이며 나쁜 예측 인자가 없고 조건이 맞는 센터에서만 조기 수술을 고려한다 [[?tg18-flowchart]]",
