   {
    "q": "도쿄 가이드라인 2018에서 급성 담낭염 2등급의 기준 네 가지는?",
    "a": "백혈구 > 18,000/mm³, 오른쪽 윗배에 만져지는 압통 덩이, 증상 발생 후 72시간 초과, 뚜렷한 국소 염증(괴저성·기종성 담낭염, 담낭 주위 농양, 간농양, 담즙성 복막염). 장기부전이 있으면 3등급이 된다."
   },
   {
    "q": "2등급 급성 담낭염에서 조기 복강경 담낭절제술과 경피경간 담낭배액을 가르는 것은 무엇인가?",
    "a": "등급이 아니라 수술 위험이다. 동반질환 지수 CCI ≤ 5·ASA ≤ 2 이고 장기부전이 없으면 숙련 센터에서 항생제와 함께 조기 복강경 담낭절제술을 하고, 수술 위험이 높으면 항생제 + 배액 뒤 간격 담낭절제로 간다."
   },
   {
    "q": "급성 담석 담낭염에서 수술 전 ERCP(또는 MRCP)를 넣는 조건은?",
    "a": "총담관결석·담관염을 의심하게 하는 소견 — 황달, 총빌리루빈·ALP 상승, 초음파의 총담관 확장, 담관염 징후 — 가 있을 때만. 경미한 AST/ALT 상승만으로는 넣지 않는다."
   },
   {
    "q": "「항생제로 가라앉힌 뒤 6주 후 담낭절제」가 기본 전략이 아닌 근거는?",
    "a": "무작위 시험(ACDC)에서 입원 24시간 안의 조기 수술이 지연 수술보다 이환율(11.8 % 대 34.4 %)과 재원기간(5.4일 대 10.0일)에서 우월했고, 기다리는 동안 재발·재입원이 흔하기 때문이다."
   }
