    "id": "cn.gs.acute-cholecystitis.grade2-early-lc#v1",
    "context": "같은 목표, 다른 조건 — 장기부전(3등급) + 고령·동반질환으로 수술 위험이 높은 환자",
    "stem": "79세 여자가 2일 전 시작된 오른쪽 윗배 통증과 열로 응급실에 왔다. 심부전(좌심실 박출률 30 %)과 만성 콩팥병으로 약을 여러 가지 먹고 있으며, 집 안에서만 겨우 걷는다. 혈압 82/50 mmHg 로 수액을 주어도 오르지 않아 노르에피네프린을 시작했고, 의식은 졸린 상태이다. 체온 38.9 ℃, 백혈구 21,000/mm³, 크레아티닌 2.6 mg/dL(평소 1.4), 총빌리루빈 1.1 mg/dL, 알칼리인산분해효소 105 U/L. 초음파에서 담낭 안 담석, 담낭벽 두께 8 mm, 담낭 주위 액체가 있고 총담관 지름 5 mm 이다. 항생제 투여와 함께 가장 적절한 처치는?",
