    "stem": "33세 여자가 2년간 임신이 되지 않아 왔다. 월경은 2–3개월에 한 번 불규칙하고 다모증이 있으며 황체기 프로게스테론이 낮다. 골반염을 두 번 앓은 병력이 있고 자궁난관조영술에서 양쪽 난관이 막혀 있으며 왼쪽 수난관이 보인다. 남편 정액검사는 정상이다. 가장 적절한 치료는?",
