    "population": "거대세포동맥염이 의심되는 시력소실(해리슨은 동맥염성 앞허혈시신경병증으로 서술)",
    "statement": "동맥염성을 빨리 알아채야 고용량 글루코코르티코이드를 즉시 시작해 두 번째 눈의 실명을 막을 수 있다. 류마티스다발근통 증상이 동반될 수 있고 적혈구침강속도·C반응단백이 대개 높다 [[harrison-21: 32장 p.223]]",
