  "pitfalls": [
   {
    "contrast": "골다공증 vs 골두 혈류 — 「뼈가 약해 나사가 안 잡히니 치환」",
    "point": "골다공증은 나사의 고정력을 떨어뜨려 고정 실패에 기여하는 부수 요인이지 수술 방법을 가르는 일차 근거가 아니다. 같은 골다공증이라도 관절낭 밖(돌기 사이) 골절은 혈류가 보존돼 골수강내 금속정·활주 고나사로 내고정한다 <sup>[1†]</sup>. 방법을 가르는 것은 뼈의 질이 아니라 <b>골절 위치(관절낭 안)와 전위가 골두 혈류를 끊었는가</b>다 <sup>[4†]</sup>.",
    "exception": "심한 골다공증은 치환술의 인공물 고정 방식(시멘트 사용)이나 돌기 사이 골절의 금속정 선택에는 영향을 준다 — 「무엇을 할지」가 아니라 「어떻게 할지」의 요인이다.",
    "cites": ""
   },
   {
    "contrast": "고령·수술 시간 vs 근거 — 「노인이니 짧은 수술」",
    "point": "관절치환술은 내고정보다 수술 시간·출혈이 오히려 많다. 고령이라서 짧은 수술을 고른다면 유관나사 고정이 맞았을 것이므로 논리가 거꾸로다. 고령이 치환 쪽으로 기우는 진짜 이유는 ① 골두 혈류 손상 뒤 재수술을 감당하기 어렵고 ② 인공물 수명이 여생을 덮으며 ③ 즉시 체중부하로 와상 합병증을 줄이기 때문이다 <sup>[2†]</sup> <sup>[1†]</sup>.",
    "exception": "젊은 환자는 같은 전위 골절이라도 인공물 수명 때문에 골두를 살리려 응급 정복·내고정을 한다.",
    "cites": ""
   },
   {
    "contrast": "관절낭 안 vs 밖 — 「정복이 어려우니 치환」",
    "point": "큰돌기·작은돌기가 온전한 넙다리뼈목 중간의 골절선은 관절낭 안이다. 관절낭 밖(돌기 사이) 골절은 혈류가 좋아 내고정하며, 「정복이 어려워서 치환」은 안·밖 개념을 뒤집은 것이다. 치환을 고르는 이유는 정복의 난이도가 아니라 정복해도 골두가 살지 못한다는 점이다 <sup>[4†]</sup>.",
    "exception": "돌기 사이 골절이라도 내고정이 실패해 불유합·고정물 파손이 온 뒤에는 구제 수술로 치환술을 한다.",
    "cites": ""
   },
   {
    "contrast": "관절면 침범 vs 혈류 — 「골절이 관절을 지나 관절염이 곧 생기니 치환」",
    "point": "넙다리뼈목 골절선은 관절연골면을 지나지 않는다. 관절염은 골두괴사가 진행한 뒤 이차적으로 생길 수 있을 뿐 치환을 택하는 일차 근거가 아니다.",
    "exception": "이미 진행된 엉덩관절 골관절염이 함께 있으면 전치환술 쪽으로 기울이는 부수 요인이 된다.",
    "cites": ""
   }
  ],
  "diagramNotes": [
   "「고령」의 절대 기준은 없다 — 여생·활동·골질·동반 질환을 함께 본다. 시험은 대개 70–80대를 준다.",
   "비전위 목 골절도 고령에서 내고정 뒤 이차 전위·괴사가 생길 수 있어 치환을 고르는 기관도 있다 — 이 예외의 근거는 원문 미대조.",
   "전치환 vs 반치환은 선호의 문제다. HEALTH 시험에서 2년 재수술률 차이가 없었다 <sup>[3†]</sup>.",
   "수술 시점: 고령 엉덩관절 골절은 내과적 안정화 뒤 되도록 24–48시간 안에 수술한다 — 지연은 합병증·사망을 늘린다(권고 문구는 원문 미대조 <sup>[1†]</sup>).",
   "수술 뒤: 즉시 체중부하·조기 보행, 정맥혈전 예방, 골다공증 치료(재골절 예방), 낙상 평가 — 골절 자체보다 이것이 예후를 정한다."
  ],
