    "population": "단순 열성경련으로 온 6~60개월 소아",
    "statement": "수막염을 시사하는 임상 징후·증상이 있으면 시행한다. 6~12개월에서 Hib·폐렴구균 접종이 부족하거나 확인할 수 없을 때, 그리고 항생제를 먼저 쓴 소아에서는 「선택지(option)」다",
    "exceptions": "option 은 「해도 되고 안 해도 되는」 가장 약한 권고 — 일률적 시행 기준이 아니다",
