    "point": "DMSA 는 급성기 신장 침범과 나중 반흔에 가장 민감하지만, 첫 열성 요로감염에서 신우신염을 확인해도 치료(항생제·기간)가 달라지지 않는다. 방사선 노출이 있고 결과가 행동을 바꾸지 않으므로 1차 영상이 아니다 <sup>[2†]</sup>. 첫 감염의 1차 영상은 구조 이상을 찾는 비침습 초음파다 <sup>[1†]</sup>.",
    "exception": "비전형·재발 감염에서 4–6개월 뒤 반흔 평가로, 또는 일부 기관의 「DMSA 먼저」 접근에서는 급성기 DMSA 를 쓴다.",
