    "point": "페니실린 10일은 급성기 인두의 사슬알균을 없애는 요법이며 1차 예방과 같은 논리다. 그러나 류마티스열의 재발은 <b>새로운</b> 사슬알균 인두 감염 때마다 일어나고, 재발할수록 심염이 더 심해진다. 그래서 급성기 제균을 마친 뒤에도 재감염 자체를 막는 2차 예방(벤자틴 페니실린 G 4주마다 근육 주사)을 심염 유무에 따라 정한 기간 동안 잇는다 <sup>[1†]</sup>. 급성기 치료를 마쳤다는 것은 예방을 끝낼 이유가 아니라 시작할 시점이다.",
