    "point": "강박 행동은 강박 사고가 일으킨 불안을 풀려는 행동이다 <sup>[1 452장 p.3546]</sup> — 불안을 약으로 눌러도 강박 사고·행동의 회로(안와전두피질·꼬리핵)는 바뀌지 않는다. 벤조디아제핀은 강박 증상 자체를 줄이지 못하고 의존만 남긴다. 다음 처치는 아직 충분히 써 보지 않은 SSRI 를 증량해 8–12주까지 유지하는 것이다 <sup>[2†]</sup>. 해리슨은 벤조디아제핀을 치료 저항 사례의 증강 선택지로 언급하지만 <sup>[1 452장 p.3546]</sup>, 그것은 충분 시도 뒤의 이야기이며 시작 용량 4주째의 답이 아니다.",
